CREATE TABLE dba.PerfLog (
  LogID INT IDENTITY PRIMARY KEY,
  CapturedAt DATETIME2 DEFAULT SYSDATETIME(),
  MetricName NVARCHAR(128),
  MetricValue BIGINT
);

-- Agent job, every 15 min:
EXEC dba.CapturePerfSnapshot;

-- Retention job, nightly:
DELETE FROM dba.PerfLog
  WHERE CapturedAt < DATEADD(DAY,-60,SYSDATETIME());
